            .recover_by_checkpoint(checkpoint)
            .await
            .expect("failed to recover");

        let recovered_entry = recovered
            .get(Chain::Solana, &sign_id)
            .await
            .expect("missing recovered entry");

        assert!(matches!(
            recovered_entry,
            BacklogEntry::SignBidirectionalPending { .. }
        ));
    }

    #[tokio::test]
