    #[tokio::test]
    async fn recover_backlog_requeues_pending_signs() {
        // Prepare backlog with a single pending sign request
        let backlog = Backlog::new();
        let sign_id = SignId::new([9u8; 32]);
        let args = SignArgs {
            entropy: [1u8; 32],
