            payload: Scalar::from(2u64),
            path: "test".to_string(),
            key_version: 1,
        };

        // Add a request and persist a checkpoint so recover() can load it
        let unix_timestamp_indexed = current_unix_timestamp();
        backlog
            .insert(test_indexed_request(
