    ) -> IndexedSignRequest {
        IndexedSignRequest::new(sign_id, args, chain, unix_timestamp_indexed, kind)
    }

    fn create_bidirectional_request(
        sign_id: SignId,
        chain: Chain,
        dest: &str,
        unix_timestamp_indexed: u64,
    ) -> IndexedSignRequest {
        IndexedSignRequest::sign_bidirectional(
            sign_id,
