        let prefix_len = dest.len().min(program_id.len());
        program_id[..prefix_len].copy_from_slice(&dest.as_bytes()[..prefix_len]);

        crate::stream::ops::SignBidirectionalEvent::Solana(SignBidirectionalEvent {
