            .await;

        backlog
            .watch_execution(tx.target_chain, sign_id, tx.clone())
            .await;

        let (sign_tx, mut sign_rx) = mpsc::channel(4);

        // Call the handler with a Success and empty output
        let tx_id = tx.id;
