        let maybe_tx = backlog.get(tx.source_chain, &sign_id).await;
        assert!(maybe_tx.is_some(), "expected sign tx to still exist");
        let tx_after = maybe_tx.unwrap();
        if tx_after.status() != SignStatus::Success {
